import{_ as t,o,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Sequence Flow — Reset Password","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-4-reset-password/sequence-flow.md","filePath":"feature/authentication/3-2-4-reset-password/sequence-flow.md"}'),i={name:"feature/authentication/3-2-4-reset-password/sequence-flow.md"};function a(d,e,c,l,u,n){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="sequence-flow-—-reset-password" tabindex="-1">Sequence Flow — Reset Password <a class="header-anchor" href="#sequence-flow-—-reset-password" aria-label="Permalink to &quot;Sequence Flow — Reset Password&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.2.4). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those).</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — actor tương tác chính trong quy trình.</li><li><strong>Client</strong> — giao diện người dùng <code>ForgotPasswordPage (UI)</code>.</li><li><strong>System</strong> — <code>AuthController</code> / <code>AuthService</code>.</li></ul><hr><h2 id="flow-a-—-luong-thuc-thi-chinh-reset-password" tabindex="-1">Flow A — Luồng thực thi chính: Reset Password <a class="header-anchor" href="#flow-a-—-luong-thuc-thi-chinh-reset-password" aria-label="Permalink to &quot;Flow A — Luồng thực thi chính: Reset Password&quot;">​</a></h2><ol><li>user -&gt; forgotpasswordpageui: <code>enters email, clicks &quot;Send Reset Link&quot;</code></li><li>forgotpasswordpageui -&gt; authcontroller: <code>POST /api/v1/auth/forgot-password (email)</code></li><li>authcontroller -&gt; authservice: <code>forgotPassword(email)</code></li><li>authservice -&gt; userrepository: <code>findByEmail(email)</code></li><li>userrepository --&gt; authservice: <code>Optional.empty()</code></li><li>authservice --&gt; authcontroller: <code>200 OK (generic — no email leak)</code></li><li>authcontroller --&gt; forgotpasswordpageui: <code>200 OK</code></li><li>forgotpasswordpageui --&gt; user: <code>&quot;If this email exists, a reset link was sent&quot;</code></li><li>userrepository --&gt; authservice: <code>Optional&lt;User&gt;</code></li><li>authservice -&gt; rediscache: <code>set(&quot;pwd:reset:&quot; + token, userId, 15 min)</code></li><li>rediscache --&gt; authservice: <code>ok</code></li><li>authservice -&gt; mailservice: <code>sendResetPasswordEmail(email, resetLink)</code></li><li>mailservice --&gt; authservice: <code>ok</code></li><li>authservice --&gt; authcontroller: <code>200 OK</code></li><li>authcontroller --&gt; forgotpasswordpageui: <code>200 OK</code></li><li>forgotpasswordpageui --&gt; user: <code>&quot;Check your email for the reset link&quot;</code></li><li>user -&gt; forgotpasswordpageui: <code>opens reset link, enters new password, clicks &quot;Reset Password&quot;</code></li><li>forgotpasswordpageui -&gt; authcontroller: <code>POST /api/v1/auth/reset-password (ResetPasswordRequest)</code></li><li>authcontroller -&gt; authservice: <code>resetPassword(token, newPassword)</code></li><li>authservice -&gt; rediscache: <code>get(&quot;pwd:reset:&quot; + token)</code></li><li>rediscache --&gt; authservice: <code>null</code></li><li>authservice --&gt; authcontroller: <code>400 Bad Request (RESET_TOKEN_INVALID)</code></li><li>authcontroller --&gt; forgotpasswordpageui: <code>400 Bad Request</code></li><li>forgotpasswordpageui --&gt; user: <code>Show error &quot;Reset link is invalid or expired&quot;</code></li><li>rediscache --&gt; authservice: <code>userId</code></li><li>authservice -&gt; userrepository: <code>save(user with encodedNewPassword)</code></li><li>userrepository --&gt; authservice: <code>ok</code></li><li>authservice -&gt; rediscache: <code>delete(&quot;pwd:reset:&quot; + token)</code></li><li>rediscache --&gt; authservice: <code>ok</code></li><li>authservice --&gt; authcontroller: <code>200 OK</code></li><li>authcontroller --&gt; forgotpasswordpageui: <code>200 OK</code></li><li>forgotpasswordpageui --&gt; user: <code>&quot;Password reset successfully — please sign in&quot;</code></li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Xác thực</td><td>Token thiếu, hết hạn hoặc không hợp lệ</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Phân quyền</td><td>Vai trò người dùng không có quyền truy cập tính năng</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Kiểm tra dữ liệu</td><td>Dữ liệu đầu vào không hợp lệ hoặc xung đột trạng thái</td><td>400</td><td><code>BAD_REQUEST</code></td></tr><tr><td>Truy vấn</td><td>Không tìm thấy bản ghi đối tượng tương ứng</td><td>404</td><td><code>NOT_FOUND</code></td></tr></tbody></table>',10)])])}const p=t(i,[["render",a]]);export{g as __pageData,p as default};
